21	
22	/**
23	 * Derives an owner's segment as '&lt;TIER&gt;_&lt;AREA&gt;': TIER is 'PREMIUM' when the effective
24	 * membershipLevel is 3 or more, otherwise 'STANDARD'; AREA is 'METRO' when the locality is a
25	 * known region (NSW, VIC or QLD), otherwise 'REGIONAL'.
26	 */
27	public final class OwnerSegment {
28	
29	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
30	
31	    private OwnerSegment() {
32	    }
33	
34	    public static String of(Owner owner) {
35	        Integer level = owner.getMembershipLevel();
36	        int effective = level != null ? level : MembershipLevel.of(owner);
37	        String tier = effective >= 3 ? "PREMIUM" : "STANDARD";
38	        String code = owner.getCustomerCode();
39	        String region = code.substring(0, code.indexOf('-'));
40	        String area = METRO_REGIONS.contains(region) ? "METRO" : "REGIONAL";
41	        return tier + "_" + area;
42	    }
43	}
